using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;

public static class TransferEndpoints
{
    public static void Map(RouteGroupBuilder t)
    {
        t.MapGet("/transfers", async (Guid tenant, AppDb db, Access a) => { await a.Member(tenant); var units = a.Visible(tenant, "members.transfer").Select(x => x.Id); var societyReview = await a.Can(tenant, "members.transfer"); return await db.MembershipTransfers.Where(x => x.TenantId == tenant && (units.Contains(x.SourceId) || units.Contains(x.DestinationId) || x.RequestedBy == a.UserId)).OrderByDescending(x => x.EffectiveAt).Take(100).Select(x => new { canReview = x.Status == "Source Review" ? units.Contains(x.SourceId) : x.Status == "Destination Review" ? units.Contains(x.DestinationId) : societyReview, x.Id, x.MembershipId, x.SourceId, x.DestinationId, x.Status, x.EffectiveAt, x.AppliedAt, x.Notes, x.Revision, name = db.Memberships.Where(m => m.Id == x.MembershipId).Select(m => db.Persons.Where(p => p.Id == m.PersonId).Select(p => p.FullName).First()).First(), source = db.Units.Where(u => u.Id == x.SourceId).Select(u => u.Name).First(), destination = db.Units.Where(u => u.Id == x.DestinationId).Select(u => u.Name).First() }).ToListAsync(); });
        t.MapPost("/transfers", async (Guid tenant, TransferRequest r, AppDb db, Access a, MembershipService s) => { await using var tx = await db.Database.BeginTransactionAsync(); await MembershipService.Lock(db, tenant); var m = await db.Memberships.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == r.MembershipId) ?? throw new AccessDeniedException(); if (!await s.IsSelf(m)) await a.Require(tenant, "members.transfer", m.ChapterId); if (m.Status != "Active" || m.EffectiveFrom > DateTimeOffset.UtcNow || m.EndsAt <= DateTimeOffset.UtcNow || m.ChapterId == r.DestinationId) throw new DomainException("Transfer an active membership to a different chapter"); await s.Chapter(tenant, r.DestinationId); var policy = await s.Policy(tenant, m.ChapterId); var transfer = new MembershipTransfer { TenantId = tenant, MembershipId = m.Id, SourceId = m.ChapterId, DestinationId = r.DestinationId, EffectiveAt = r.EffectiveAt.ToUniversalTime(), RequestedBy = a.UserId, Notes = r.Notes, Status = policy.SourceTransferReview ? "Source Review" : "Destination Review", SocietyReview = policy.SocietyTransferReview }; db.MembershipTransfers.Add(transfer); s.History(m, a.UserId, "transfer.requested", new { transfer.Id, transfer.SourceId, transfer.DestinationId }); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.Ok(new { transfer.Id }); });
        t.MapPost("/transfers/{id:guid}/decision", async (Guid tenant, Guid id, MemberDecisionRequest r, AppDb db, Access a, MembershipService s) => { await using var tx = await db.Database.BeginTransactionAsync(); await MembershipService.Lock(db, tenant); var transfer = await db.MembershipTransfers.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); if (transfer.Revision != r.Revision) return Results.Conflict(); if (transfer.Status is "Effective" or "Approved" or "Rejected") throw new DomainException("Transfer already decided"); Guid? scope = transfer.Status == "Source Review" ? transfer.SourceId : transfer.Status == "Destination Review" ? transfer.DestinationId : null; await a.Require(tenant, "members.transfer", scope); if (r.Decision is not ("Approve" or "Reject")) throw new DomainException("Choose approve or reject"); if (r.Decision == "Reject") transfer.Status = "Rejected"; else if (transfer.Status == "Source Review") transfer.Status = "Destination Review"; else if (transfer.Status == "Destination Review" && transfer.SocietyReview) transfer.Status = "Society Review"; else transfer.Status = "Approved"; transfer.Revision++; var m = await db.Memberships.SingleAsync(x => x.TenantId == tenant && x.Id == transfer.MembershipId); s.History(m, a.UserId, "transfer.decision", new { transfer.Id, transfer.Status, comment = r.Comment }); if (transfer.Status == "Approved" && transfer.EffectiveAt <= DateTimeOffset.UtcNow) await Apply(transfer, db, s, a.UserId); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.Ok(new { transfer.Status }); });
    }
    public static async Task Apply(MembershipTransfer transfer, AppDb db, MembershipService s, Guid actor) { if (transfer.Status != "Approved" || transfer.AppliedAt != null) return; var m = await db.Memberships.SingleAsync(x => x.TenantId == transfer.TenantId && x.Id == transfer.MembershipId); if (m.ChapterId != transfer.SourceId || m.Status != "Active" || m.EndsAt <= DateTimeOffset.UtcNow) throw new DomainException("Membership changed before the transfer became effective"); await s.Chapter(transfer.TenantId, transfer.DestinationId); if (await db.Memberships.AnyAsync(x => x.TenantId == transfer.TenantId && x.PersonId == m.PersonId && x.ChapterId == transfer.DestinationId && x.Id != m.Id && x.Status != "Closed")) throw new DomainException("An active destination affiliation already exists"); await s.RevokeOfficers(m, actor); var person = await db.Persons.SingleAsync(p => p.Id == m.PersonId); if (person.UserId != null) { var oldRoots = await MembershipService.Ancestors(db, m.TenantId, transfer.SourceId); var newRoots = await MembershipService.Ancestors(db, m.TenantId, transfer.DestinationId); var lostRoots = oldRoots.Except(newRoots).ToArray(); var grants = await db.Assignments.Where(a => a.TenantId == m.TenantId && a.UserId == person.UserId && a.MembershipId == null && a.UnitId != null && lostRoots.Contains(a.UnitId.Value) && a.RevokedAt == null).ToListAsync(); foreach (var grant in grants) grant.RevokedAt = DateTimeOffset.UtcNow; s.History(m, actor, "transfer.source.grants.revoked", new { count = grants.Count }); } var directoryAssignments = await (from assignment in db.Assignments join role in db.GovernanceRoles on assignment.RoleId equals role.Id where assignment.TenantId == m.TenantId && assignment.MembershipId == m.Id && role.Name == "Member Directory" select assignment).ToListAsync(); foreach (var assignment in directoryAssignments) assignment.UnitId = transfer.DestinationId; var committees = await db.CommitteeMemberships.Where(x => x.TenantId == m.TenantId && x.MembershipId == m.Id && x.EndsAt == null && db.Committees.Any(c => c.Id == x.CommitteeId && c.UnitId == transfer.SourceId)).ToListAsync(); foreach (var cm in committees) cm.EndsAt = DateTimeOffset.UtcNow; m.ChapterId = transfer.DestinationId; m.Revision++; transfer.Status = "Effective"; transfer.AppliedAt = DateTimeOffset.UtcNow; transfer.Revision++; s.History(m, actor, "transfer.effective", new { transfer.Id, transfer.SourceId, transfer.DestinationId, originalJoiningDate = m.JoinedAt }); }
}
